<script setup lang="ts">
import{onMounted}from'vue';import{storeToRefs}from'pinia';import{RouterLink}from'vue-router';import FinanceScenarioBar from'../components/FinanceScenarioBar.vue';import FinanceSubnav from'../components/FinanceSubnav.vue';import{useFinanceStore}from'../runtime/finance-store';import type{FinanceRole}from'../types';import type{FinanceScenarioName}from'../../../../mock/handlers/finance-handler';import'./finance-views.css';import'./finance-receivable-views.css'
const store=useFinanceStore();const{writeoffs,loading,error,scenario,actor}=storeToRefs(store);const money=(v:number)=>`¥${(v/100).toFixed(2)}`;async function refresh(){await store.loadWriteoffs()}async function scenarioChange(v:FinanceScenarioName){await store.setScenario(v);await refresh()}async function roleChange(v:FinanceRole){await store.setRole(v);await refresh()}async function cancel(id:string,version:number){const reason=window.prompt('请输入整张取消原因（1～200字）');if(reason)await store.cancelWriteoff(id,version,reason)}onMounted(refresh)
</script>
<template><section class="finance-page"><header class="finance-header"><div><h1>收款核销</h1><p>同一客户手工多对多分配；核销不再次移动资金账户，取消会恢复原来源。</p></div><FinanceScenarioBar :scenario="scenario" :role="actor.role" @scenario="scenarioChange" @role="roleChange"/></header><FinanceSubnav/><div class="finance-toolbar"><span>共 {{writeoffs.length}} 张核销单</span><div><button class="fin-button" @click="refresh">刷新</button><RouterLink v-if="actor.role!=='sales-supervisor'" class="fin-button primary" to="/finance/writeoffs/new">新增核销</RouterLink></div></div><div v-if="error" class="finance-state error">{{error}}</div><div v-else-if="loading" class="finance-state">正在加载核销单…</div><div v-else class="finance-table-wrap"><table class="finance-table"><thead><tr><th>核销单号/日期</th><th>客户</th><th class="fin-money">现金/预收</th><th class="fin-money">优惠</th><th class="fin-money">核销金额</th><th>分配数</th><th>操作人</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in writeoffs" :key="row.id"><td><RouterLink :to="`/finance/writeoffs/${row.id}`"><strong>{{row.writeoffNo}}</strong></RouterLink><small>{{row.occurredAt.slice(0,16).replace('T',' ')}}</small></td><td>{{row.customerId}}</td><td class="fin-money">{{money(row.cashCents)}}</td><td class="fin-money">{{money(row.discountCents)}}</td><td class="fin-money"><strong>{{money(row.amountCents)}}</strong></td><td>{{row.allocations.length}}</td><td>{{row.operatorSnapshot.name}}</td><td><span class="fin-status" :class="row.status==='active'?'enabled':'disabled'">{{row.status==='active'?'有效':'已取消'}}</span></td><td><RouterLink :to="`/finance/writeoffs/${row.id}`">查看</RouterLink> <button v-if="row.status==='active'&&actor.role!=='sales-supervisor'" class="fin-link-button danger" @click="cancel(row.id,row.version)">取消</button></td></tr><tr v-if="!writeoffs.length"><td colspan="9">暂无核销单</td></tr></tbody></table></div></section></template>
